cat > /tmp/TestHelpers.java <<'EOF'
import java.lang.reflect.Method;

public class TestHelpers {
    public static void main(String[] args) throws Exception {
        Class<?> cls = Class.forName("com.modelgate.platform.service.ProviderService");
        Object svc = cls.getDeclaredConstructor().newInstance();
        Method get = cls.getDeclaredMethod("sendGetRequest", String.class, String.class);
        Method post = cls.getDeclaredMethod("sendPostRequest", String.class, String.class, String.class);
        get.setAccessible(true);
        post.setAccessible(true);
        System.out.println("GET /models/x -> " + get.invoke(svc, "http://127.0.0.1:8899/models/x", "sk-abc"));
        System.out.println("GET /other   -> " + get.invoke(svc, "http://127.0.0.1:8899/other", "sk-abc"));
        System.out.println("GET bad url  -> " + get.invoke(svc, "http://127.0.0.1:1/nope", "sk-abc"));
        System.out.println("GET malformed-> " + get.invoke(svc, "not a url", "sk-abc"));
        String body = "{\"model\":\"gpt-x\",\"messages\":[{\"role\":\"user\",\"content\":\"Hello\"}],\"max_tokens\":1}";
        System.out.println("POST /v1/chat/completions -> " + post.invoke(svc, "http://127.0.0.1:8899/v1/chat/completions", "sk-abc", body));
        System.out.println("POST refused -> " + post.invoke(svc, "http://127.0.0.1:1/v1/chat/completions", "sk-abc", body));
    }
}
EOF
cd /workspace && javac -cp "target/classes:$(cat /tmp/cp.txt)" -d /tmp /tmp/TestHelpers.java && java -cp "/tmp:target/classes:$(cat /tmp/cp.txt)" TestHelpers; echo ---MOCKLOG---; cat /tmp/mock_provider.log

