input.command:
cat > /tmp/RawConn.java <<'EOF'
import java.net.*;
public class RawConn {
    public static void main(String[] args) throws Exception {
        try {
            URL url = new URL("http://127.0.0.1:8899/models/x");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setRequestProperty("Authorization", "Bearer sk-abc");
            conn.setConnectTimeout(10000);
            conn.setReadTimeout(10000);
            System.out.println("code=" + conn.getResponseCode());
        } catch (Exception e) {
            e.printStackTrace();
        }
        System.out.println("proxyHost=" + System.getProperty("http.proxyHost") + " nonProxy=" + System.getProperty("http.nonProxyHosts"));
        System.out.println("env http_proxy=" + System.getenv("http_proxy") + " HTTP_PROXY=" + System.getenv("HTTP_PROXY"));
    }
}
EOF
cd /tmp && javac RawConn.java && java RawConn; echo ---; cat /tmp/mock_provider.log; env | grep -i proxy

